## Secure Implementation

### Tier 1: Critical Fix (10 min)

**Enable CSRF protection and validate tokens on all state-changing endpoints**

```java
// ✅ SECURE: CSRF protection enabled (Spring Security default)

package com.example.banking.config;

import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;
import org.springframework.security.config.annotation.web.builders.HttpSecurity;
import org.springframework.security.web.SecurityFilterChain;
import org.springframework.security.web.csrf.CookieCsrfTokenRepository;

@Configuration
public class SecureSecurityConfig {

    @Bean
    public SecurityFilterChain filterChain(HttpSecurity http) throws Exception {
        http
            .authorizeHttpRequests(authz -> authz
                .requestMatchers("/api/**").authenticated()
                .anyRequest().permitAll()
            )
            // ✅ CSRF protection enabled (default behavior)
            // Automatically validates tokens on POST, PUT, DELETE, PATCH
            .csrf(csrf -> csrf
                // ✅ Use cookie-based token repository for REST APIs
                .csrfTokenRepository(CookieCsrfTokenRepository.withHttpOnlyFalse())
            );

        return http.build();
    }
}

package com.example.banking.controller;

