### Tier 2: Essential Defenses (20 min)

**Add STOMP CSRF protection, referer validation, and per-request token rotation**

```java
// ✅ SECURE: STOMP WebSocket with CSRF validation (fixes CVE-2023-34035)

package com.example.banking.config;

import org.springframework.context.annotation.Configuration;
import org.springframework.messaging.simp.config.ChannelRegistration;
import org.springframework.messaging.simp.config.MessageBrokerRegistry;
import org.springframework.security.messaging.context.SecurityContextChannelInterceptor;
import org.springframework.web.socket.config.annotation.*;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.security.web.csrf.CsrfToken;
import org.springframework.messaging.Message;
import org.springframework.messaging.MessageChannel;
import org.springframework.messaging.simp.stomp.StompCommand;
import org.springframework.messaging.simp.stomp.StompHeaderAccessor;
import org.springframework.messaging.support.ChannelInterceptor;
import org.springframework.messaging.support.MessageHeaderAccessor;

@Configuration
@EnableWebSocketMessageBroker
public class SecureWebSocketConfig implements WebSocketMessageBrokerConfigurer {

    @Override
    public void configureMessageBroker(MessageBrokerRegistry config) {
        config.enableSimpleBroker("/topic");
        config.setApplicationDestinationPrefixes("/app");
    }

    @Override
    public void registerStompEndpoints(StompEndpointRegistry registry) {
        registry.addEndpoint("/ws-transfer")
                // ✅ Restrict to specific origins (not wildcard)
                .setAllowedOrigins(
                    "https://bank.com",
                    "https://www.bank.com"
                )
                .withSockJS();
    }

    @Override
    public void configureClientInboundChannel(ChannelRegistration registration) {
        // ✅ Add CSRF validation for STOMP frames
        registration.interceptors(
            new SecurityContextChannelInterceptor(),
            new CsrfChannelInterceptor()  // ✅ Validates CSRF tokens
        );
    }
}

// ✅ Custom CSRF channel interceptor for STOMP messages
class CsrfChannelInterceptor implements ChannelInterceptor {

    @Override
    public Message<?> preSend(Message<?> message, MessageChannel channel) {
        StompHeaderAccessor accessor = 
            MessageHeaderAccessor.getAccessor(message, StompHeaderAccessor.class);

        if (accessor != null && StompCommand.CONNECT.equals(accessor.getCommand())) {
            // ✅ CRITICAL: Validate CSRF token on CONNECT frames
            // Prevents CVE-2023-34035 exploitation

            String csrfToken = accessor.getFirstNativeHeader("X-CSRF-TOKEN");

            if (csrfToken == null || csrfToken.isEmpty()) {
                throw new SecurityException("CSRF token missing from STOMP CONNECT");
            }

            // ✅ Validate token against session
            // Implementation depends on your CsrfTokenRepository
            validateCsrfToken(csrfToken, accessor.getSessionAttributes());
        }

        return message;
    }

    private void validateCsrfToken(String token, Map<String, Object> sessionAttrs) {
        CsrfToken expectedToken = (CsrfToken) sessionAttrs.get(CsrfToken.class.getName());
        if (expectedToken == null || !expectedToken.getToken().equals(token)) {
            throw new SecurityException("Invalid CSRF token");
        }
    }
}

package com.example.banking.config;

import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;
import org.springframework.security.config.annotation.web.builders.HttpSecurity;
import org.springframework.security.web.SecurityFilterChain;
import org.springframework.security.web.csrf.CookieCsrfTokenRepository;
import org.springframework.security.web.csrf.CsrfTokenRequestAttributeHandler;

@Configuration
public class EnhancedSecurityConfig {

    @Bean
    public SecurityFilterChain filterChain(HttpSecurity http) throws Exception {
        http
            .authorizeHttpRequests(authz -> authz
                .requestMatchers("/api/**").authenticated()
                .anyRequest().permitAll()
            )
            .csrf(csrf -> csrf
                .csrfTokenRepository(CookieCsrfTokenRepository.withHttpOnlyFalse())
                // ✅ Per-request token rotation (Spring Security 6.0+)
                .csrfTokenRequestHandler(new CsrfTokenRequestAttributeHandler())
                // ✅ Require CSRF tokens on all state-changing methods
                .requireCsrfProtectionMatcher(request -> {
                    String method = request.getMethod();
                    return method.equals("POST") || 
                           method.equals("PUT") || 
                           method.equals("DELETE") ||
                           method.equals("PATCH");
                })
            );

        return http.build();
    }
}

package com.example.banking.filter;

import javax.servlet.*;
import javax.servlet.http.HttpServletRequest;
import javax.servlet.http.HttpServletResponse;
import java.io.IOException;
import java.util.Arrays;
import java.util.List;

// ✅ Referer header validation filter (defense in depth)
public class RefererValidationFilter implements Filter {

    private static final List<String> ALLOWED_REFERERS = Arrays.asList(
        "https://bank.com",
        "https://www.bank.com"
    );

    @Override
    public void doFilter(ServletRequest request, ServletResponse response, 
                         FilterChain chain) throws IOException, ServletException {

        HttpServletRequest httpRequest = (HttpServletRequest) request;
        HttpServletResponse httpResponse = (HttpServletResponse) response;

        String method = httpRequest.getMethod();

        // ✅ Validate referer on state-changing requests
        if (method.equals("POST") || method.equals("PUT") || 
            method.equals("DELETE") || method.equals("PATCH")) {

            String referer = httpRequest.getHeader("Referer");

            if (referer == null || referer.isEmpty()) {
                httpResponse.setStatus(HttpServletResponse.SC_FORBIDDEN);
                httpResponse.getWriter().write("Missing referer header");
                return;
            }

            boolean validReferer = ALLOWED_REFERERS.stream()
                .anyMatch(referer::startsWith);

            if (!validReferer) {
                httpResponse.setStatus(HttpServletResponse.SC_FORBIDDEN);
                httpResponse.getWriter().write("Invalid referer");
                return;
            }
        }

        chain.doFilter(request, response);
    }
}
```

### Tier 3: Production Hardening (45 min)

**Add rate limiting, origin validation, audit logging, and comprehensive monitoring**

```java
package com.example.banking.config;

import io.github.bucket4j.Bandwidth;
import io.github.bucket4j.Bucket;
import io.github.bucket4j.Refill;
import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;
import org.springframework.security.config.annotation.web.builders.HttpSecurity;
import org.springframework.security.web.SecurityFilterChain;
import org.springframework.security.web.csrf.CookieCsrfTokenRepository;
import org.springframework.security.web.csrf.CsrfTokenRequestAttributeHandler;
import org.springframework.web.cors.CorsConfiguration;
import org.springframework.web.cors.CorsConfigurationSource;
import org.springframework.web.cors.UrlBasedCorsConfigurationSource;
import java.time.Duration;
import java.util.Arrays;
import java.util.concurrent.ConcurrentHashMap;

@Configuration
public class ProductionSecurityConfig {

    @Bean
    public SecurityFilterChain filterChain(HttpSecurity http) throws Exception {
        http
            .authorizeHttpRequests(authz -> authz
                .requestMatchers("/api/**").authenticated()
                .anyRequest().permitAll()
            )
            // ✅ Strict CORS configuration
            .cors(cors -> cors.configurationSource(corsConfigurationSource()))
            .csrf(csrf -> csrf
                .csrfTokenRepository(CookieCsrfTokenRepository.withHttpOnlyFalse())
                .csrfTokenRequestHandler(new CsrfTokenRequestAttributeHandler())
            )
            // ✅ Custom headers for additional security
            .headers(headers -> headers
                .contentSecurityPolicy(csp -> csp
                    .policyDirectives("default-src 'self'; frame-ancestors 'none'")
                )
            );

        return http.build();
    }

    @Bean
    public CorsConfigurationSource corsConfigurationSource() {
        CorsConfiguration configuration = new CorsConfiguration();

        // ✅ Explicitly allow only trusted origins
        configuration.setAllowedOrigins(Arrays.asList(
            "https://bank.com",
            "https://www.bank.com"
        ));

        configuration.setAllowedMethods(Arrays.asList("GET", "POST", "PUT", "DELETE"));
        configuration.setAllowedHeaders(Arrays.asList("*"));
        configuration.setAllowCredentials(true);  // Allow cookies
        configuration.setMaxAge(3600L);

        UrlBasedCorsConfigurationSource source = new UrlBasedCorsConfigurationSource();
        source.registerCorsConfiguration("/api/**", configuration);
        return source;
    }
}

package com.example.banking.filter;

import io.github.bucket4j.Bandwidth;
import io.github.bucket4j.Bucket;
import io.github.bucket4j.Refill;
import javax.servlet.*;
import javax.servlet.http.HttpServletRequest;
import javax.servlet.http.HttpServletResponse;
import java.io.IOException;
import java.time.Duration;
import java.util.concurrent.ConcurrentHashMap;

// ✅ Rate limiting filter to prevent brute-force CSRF attempts
public class RateLimitingFilter implements Filter {

    private final ConcurrentHashMap<String, Bucket> buckets = new ConcurrentHashMap<>();

    private Bucket createBucket() {
        // ✅ Allow 10 requests per minute per IP
        Bandwidth limit = Bandwidth.classic(
            10, 
            Refill.intervally(10, Duration.ofMinutes(1))
        );
        return Bucket.builder().addLimit(limit).build();
    }

    @Override
    public void doFilter(ServletRequest request, ServletResponse response,
                         FilterChain chain) throws IOException, ServletException {

        HttpServletRequest httpRequest = (HttpServletRequest) request;
        HttpServletResponse httpResponse = (HttpServletResponse) response;

        String clientIp = getClientIp(httpRequest);
        Bucket bucket = buckets.computeIfAbsent(clientIp, k -> createBucket());

        if (bucket.tryConsume(1)) {
            chain.doFilter(request, response);
        } else {
            httpResponse.setStatus(429);  // Too Many Requests
            httpResponse.getWriter().write("Rate limit exceeded");
        }
    }

    private String getClientIp(HttpServletRequest request) {
        String forwarded = request.getHeader("X-Forwarded-For");
        return (forwarded != null) ? forwarded.split(",")[0] : request.getRemoteAddr();
    }
}

package com.example.banking.audit;

import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.stereotype.Component;
import org.springframework.web.servlet.HandlerInterceptor;
import javax.servlet.http.HttpServletRequest;
import javax.servlet.http.HttpServletResponse;

// ✅ Audit logging interceptor for CSRF events
@Component
public class CsrfAuditInterceptor implements HandlerInterceptor {

    private static final Logger auditLog = LoggerFactory.getLogger("CSRF_AUDIT");

    @Override
    public boolean preHandle(HttpServletRequest request, 
                            HttpServletResponse response, 
                            Object handler) {

        String method = request.getMethod();

        if (method.equals("POST") || method.equals("PUT") || 
            method.equals("DELETE") || method.equals("PATCH")) {

            String csrfToken = request.getHeader("X-XSRF-TOKEN");
            String referer = request.getHeader("Referer");
            String origin = request.getHeader("Origin");
            String userAgent = request.getHeader("User-Agent");
            String clientIp = getClientIp(request);

            // ✅ Log all state-changing requests for forensics
            auditLog.info("CSRF_REQUEST: method={}, uri={}, csrfPresent={}, " +
                         "referer={}, origin={}, ip={}, userAgent={}",
                method,
                request.getRequestURI(),
                csrfToken != null,
                referer,
                origin,
                clientIp,
                userAgent
            );

            // ✅ Alert on suspicious patterns
            if (csrfToken == null) {
                auditLog.warn("CSRF_TOKEN_MISSING: uri={}, ip={}, referer={}",
                    request.getRequestURI(), clientIp, referer
                );
            }

            if (referer == null || origin == null) {
                auditLog.warn("CSRF_HEADERS_MISSING: uri={}, ip={}, " +
                             "refererPresent={}, originPresent={}",
                    request.getRequestURI(), clientIp, 
                    referer != null, origin != null
                );
            }
        }

        return true;
    }

    private String getClientIp(HttpServletRequest request) {
        String forwarded = request.getHeader("X-Forwarded-For");
        return (forwarded != null) ? forwarded.split(",")[0] : request.getRemoteAddr();
    }
}

