import javax.servlet.http.HttpServletResponse;

// ✅ Custom CSRF token repository with Prometheus metrics
public class MetricsEnabledCsrfTokenRepository implements CsrfTokenRepository {

    private final CsrfTokenRepository delegate;
    private final Counter csrfTokenGeneratedCounter;
    private final Counter csrfTokenValidationFailureCounter;

    public MetricsEnabledCsrfTokenRepository(
            CsrfTokenRepository delegate,
            MeterRegistry meterRegistry) {

        this.delegate = delegate;

        this.csrfTokenGeneratedCounter = Counter.builder("csrf_token_generated_total")
            .description("Total CSRF tokens generated")
            .register(meterRegistry);

        this.csrfTokenValidationFailureCounter = Counter.builder("csrf_validation_failure_total")
            .description("Total CSRF validation failures")
            .tag("reason", "token_mismatch")
            .register(meterRegistry);
    }

    @Override
    public CsrfToken generateToken(HttpServletRequest request) {
        CsrfToken token = delegate.generateToken(request);
        csrfTokenGeneratedCounter.increment();
        return token;
    }

    @Override
    public void saveToken(CsrfToken token, HttpServletRequest request,
                         HttpServletResponse response) {
        delegate.saveToken(token, request, response);
    }

    @Override
    public CsrfToken loadToken(HttpServletRequest request) {
        return delegate.loadToken(request);
    }
}
