## Advanced: Custom CSRF Token Provider

```java
package com.example.banking.security;

import org.springframework.security.web.csrf.CsrfToken;
import org.springframework.security.web.csrf.CsrfTokenRepository;
import org.springframework.security.web.csrf.DefaultCsrfToken;
import javax.servlet.http.HttpServletRequest;
import javax.servlet.http.HttpServletResponse;
import javax.servlet.http.HttpSession;
import java.security.SecureRandom;
import java.util.Base64;

// ✅ Custom CSRF token repository with per-request rotation
public class RotatingCsrfTokenRepository implements CsrfTokenRepository {

    private static final String CSRF_TOKEN_ATTR_NAME = "_csrf";
    private static final String CSRF_HEADER_NAME = "X-XSRF-TOKEN";
    private static final String CSRF_PARAMETER_NAME = "_csrf";
    private static final SecureRandom secureRandom = new SecureRandom();

    @Override
    public CsrfToken generateToken(HttpServletRequest request) {
        // ✅ Generate cryptographically secure random token
        byte[] tokenBytes = new byte[32];
        secureRandom.nextBytes(tokenBytes);
        String token = Base64.getUrlEncoder().withoutPadding().encodeToString(tokenBytes);

        return new DefaultCsrfToken(CSRF_HEADER_NAME, CSRF_PARAMETER_NAME, token);
    }

    @Override
    public void saveToken(CsrfToken token, HttpServletRequest request,
                         HttpServletResponse response) {

        HttpSession session = request.getSession(false);

        if (token == null) {
            if (session != null) {
                session.removeAttribute(CSRF_TOKEN_ATTR_NAME);
            }
        } else {
            if (session == null) {
                session = request.getSession();
            }

            // ✅ Store in session for server-side validation
            session.setAttribute(CSRF_TOKEN_ATTR_NAME, token);

            // ✅ Also send in cookie for client access
            response.addCookie(createCsrfCookie(token.getToken()));
        }
    }

    @Override
    public CsrfToken loadToken(HttpServletRequest request) {
        HttpSession session = request.getSession(false);
        if (session == null) {
            return null;
        }
        return (CsrfToken) session.getAttribute(CSRF_TOKEN_ATTR_NAME);
    }

    private javax.servlet.http.Cookie createCsrfCookie(String token) {
        javax.servlet.http.Cookie cookie = new javax.servlet.http.Cookie("XSRF-TOKEN", token);
        cookie.setHttpOnly(false);  // Allow JS to read for header inclusion
        cookie.setSecure(true);     // HTTPS only
        cookie.setPath("/");
        cookie.setMaxAge(-1);       // Session cookie
        // Note: SameSite set via application.properties
        return cookie;
    }
}
```

