## Hybrid Approach: Session + JWT for SPAs

Some applications use session cookies for web UI and JWT for API calls. This requires careful CSRF handling.

```java
// ✅ SECURE: Hybrid authentication with conditional CSRF

package com.example.banking.config;

import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;
import org.springframework.security.config.annotation.web.builders.HttpSecurity;
import org.springframework.security.web.SecurityFilterChain;
import org.springframework.security.web.csrf.CookieCsrfTokenRepository;
import org.springframework.security.web.util.matcher.AntPathRequestMatcher;
import org.springframework.security.web.util.matcher.OrRequestMatcher;
import org.springframework.security.web.util.matcher.RequestMatcher;

@Configuration
public class HybridSecurityConfig {

    @Bean
    public SecurityFilterChain filterChain(HttpSecurity http) throws Exception {
        http
            .authorizeHttpRequests(authz -> authz
                .requestMatchers("/api/auth/**").permitAll()
                .requestMatchers("/api/**").authenticated()
            )
            .csrf(csrf -> csrf
                // ✅ Require CSRF only for requests without JWT
                .requireCsrfProtectionMatcher(new RequestMatcher() {
                    @Override
                    public boolean matches(HttpServletRequest request) {
                        // Check if request has JWT in Authorization header
                        String authHeader = request.getHeader("Authorization");
                        boolean hasJwt = authHeader != null && authHeader.startsWith("Bearer ");

                        // If JWT present, skip CSRF (stateless)
                        if (hasJwt) {
                            return false;
                        }

                        // If no JWT, require CSRF for state-changing methods
                        String method = request.getMethod();
                        return method.equals("POST") || method.equals("PUT") ||
                               method.equals("DELETE") || method.equals("PATCH");
                    }
                })
                .csrfTokenRepository(CookieCsrfTokenRepository.withHttpOnlyFalse())
            );

        return http.build();
    }
}
```

