## Mobile Apps & CSRF

**Mobile apps (iOS/Android) do NOT need CSRF protection:**

1. Mobile HTTP clients (URLSession, OkHttp) don't have browser cookie behavior
2. Apps explicitly include authentication tokens in headers
3. No automatic credential inclusion like browsers
4. Attacker cannot force victim's app to make requests

**Mobile JWT Implementation:**

```kotlin
// ✅ SECURE: Android app with JWT (Kotlin)

class ApiClient {
    private val client = OkHttpClient()
    private var jwtToken: String? = null

    fun login(username: String, password: String): Boolean {
        val json = JSONObject().apply {
            put("username", username)
            put("password", password)
        }

        val requestBody = json.toString().toRequestBody(
            "application/json".toMediaType()
        )

        val request = Request.Builder()
            .url("https://bank.com/api/auth/login")
            .post(requestBody)
            .build()

        client.newCall(request).execute().use { response ->
            if (response.isSuccessful) {
                val responseData = JSONObject(response.body?.string() ?: "")
                jwtToken = responseData.getString("token")

                // ✅ Store token securely in Keystore
                storeTokenInKeystore(jwtToken!!)
                return true
            }
        }

        return false
    }

    fun makeAuthenticatedRequest(url: String, method: String, body: JSONObject?): JSONObject? {
        val token = jwtToken ?: loadTokenFromKeystore() ?: return null

        val requestBuilder = Request.Builder()
            .url(url)
            // ✅ Explicitly include JWT in header
            .addHeader("Authorization", "Bearer $token")

        when (method) {
            "POST" -> requestBuilder.post(
                body?.toString()?.toRequestBody("application/json".toMediaType())
                    ?: ByteArray(0).toRequestBody()
            )
            "PUT" -> requestBuilder.put(
                body?.toString()?.toRequestBody("application/json".toMediaType())
                    ?: ByteArray(0).toRequestBody()
            )
            "DELETE" -> requestBuilder.delete()
            else -> requestBuilder.get()
        }

        val request = requestBuilder.build()

        client.newCall(request).execute().use { response ->
            return if (response.isSuccessful) {
                JSONObject(response.body?.string() ?: "{}")
            } else {
                null
            }
        }
    }

    private fun storeTokenInKeystore(token: String) {
        // Use Android Keystore for secure storage
    }

    private fun loadTokenFromKeystore(): String? {
        // Retrieve from Android Keystore
        return null
    }
}

// Usage
val apiClient = ApiClient()
apiClient.login("user@example.com", "password")

// Transfer funds (no CSRF token needed)
